package com.vahotel.service;
import com.vahotel.model.OtpToken;import com.vahotel.repo.OtpTokenRepository;import java.security.SecureRandom;import java.time.LocalDateTime;import org.springframework.beans.factory.ObjectProvider;import org.springframework.beans.factory.annotation.Value;import org.springframework.mail.SimpleMailMessage;import org.springframework.mail.javamail.JavaMailSender;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;
@Service public class OtpService {private final OtpTokenRepository repo;private final PasswordEncoder encoder;private final ObjectProvider<JavaMailSender> mail;private final SecureRandom random=new SecureRandom();@Value("${spring.mail.username:}") private String sender;@Value("${spring.mail.host:}") private String mailHost;@Value("${va.hotel.otp.log-to-console:true}") private boolean logOtp;
 public OtpService(OtpTokenRepository r,PasswordEncoder e,ObjectProvider<JavaMailSender> m){repo=r;encoder=e;mail=m;}
 public void send(String email){String code=String.format("%06d",random.nextInt(1_000_000));repo.findTopByEmailAndUsedFalseOrderByIdDesc(email).ifPresent(t->{t.setUsed(true);repo.save(t);});repo.save(new OtpToken(email,encoder.encode(code),LocalDateTime.now().plusMinutes(10)));JavaMailSender senderBean=mail.getIfAvailable();if(senderBean!=null&&!sender.isBlank()&&!mailHost.isBlank()){SimpleMailMessage msg=new SimpleMailMessage();msg.setFrom(sender);msg.setTo(email);msg.setSubject("VA Hotel email verification");msg.setText("Your verification code is "+code+". It expires in 10 minutes.");senderBean.send(msg);}else if(logOtp)System.out.println("VA HOTEL DEVELOPMENT OTP for "+email+": "+code);}
 public boolean verify(String email,String code){var found=repo.findTopByEmailAndUsedFalseOrderByIdDesc(email);if(found.isEmpty()||found.get().getExpiresAt().isBefore(LocalDateTime.now())||!encoder.matches(code,found.get().getCodeHash()))return false;found.get().setUsed(true);repo.save(found.get());return true;}}
